---@class UIActivityMultipleSignCellNode
---@field TxtNumber                      TMPro.TextMeshProUGUI
---@field TxtDay                         TMPro.TextMeshProUGUI
---@field FloorFinish                    UnityEngine.RectTransform
---@field FloorReceived                  UnityEngine.RectTransform
---@field FloorNormal                    UnityEngine.RectTransform
---@field FontStyleButton                UnityEngine.RectTransform
---@field ImgInk                         UnityEngine.RectTransform
---@field TxtState                       UnityEngine.RectTransform
---@field ImgFinish                      UnityEngine.RectTransform
---@field CommonGoodsList                UnityEngine.RectTransform
---@field AnimRoot                       UnityEngine.RectTransform
---@field Imgbg                          UnityEngine.CanvasRenderer
---@field Black                          UnityEngine.RectTransform
---@field CanAnim                        UnityEngine.RectTransform

local UIActivityMultipleSignCellNode = Class('UIActivityMultipleSignCellNode')
local KTool        = CS.Engine.Lib.KTool
local XLuaUtils    = CS.Engine.Lib.XLuaUtils

function UIActivityMultipleSignCellNode:__init()
    self.cellIndex  = -1
    self.isAnimate = false
end

function UIActivityMultipleSignCellNode:__delete()
    
end

function UIActivityMultipleSignCellNode:Awake()
    SetButtonAction(self.FontStyleButton, function ()
        if self.btnAction and type(self.btnAction) == 'function' then
            self.btnAction(self.signDt.id, self.signDt.accumulativeLoginNum, self.cellIndex)
        end
    end)
end

function UIActivityMultipleSignCellNode:SetBtnAction(handler)
    self.btnAction = handler
end

function UIActivityMultipleSignCellNode:PlayFadeInAnim(index)
    if not self.isAnimate then
        if not isNull(self.AnimRoot) then
            self.isAnimate = true
            CfUtils.PlayAnimator(self.AnimRoot, "Wait")
            CfUtils.PlayDelayShowAnimate(self.AnimRoot, 1, (index or 1) * 0.1)
        end
    else 
        self:PlayInitAnim()    
    end
   
end

function UIActivityMultipleSignCellNode:RefreshSelf(data, curDay, cellIndex)
    if not data or next(data) == nil then
        return
    end

    self.signDt    = data
    self.cellIndex = cellIndex or self.cellIndex
    curDay = checkInt(curDay)

    self.TxtNumber.text = tostring(data.accumulativeLoginNum)

    local isCanGet = checkInt(data.status) == Constants.GetStatus.Can
    local isGot    = checkInt(data.status) == Constants.GetStatus.Has
    local isDoing  = checkInt(data.status) == Constants.GetStatus.Not
    if not isNull(self.FloorFinish) then
        KTool.SetActive(self.FloorFinish, isGot)
    end
    if not isNull(self.FloorReceived) then
        KTool.SetActive(self.FloorReceived, isCanGet)
    end
    KTool.SetActive(self.FontStyleButton, isCanGet)
    KTool.SetActive(self.ImgFinish, isGot)

    local isTomorrow = curDay == (checkInt(data.accumulativeLoginNum) - 1)
    KTool.SetActive(self.TxtState, isTomorrow or isDoing)
    KTool.SetActive(self.ImgInk, isTomorrow)
    KTool.SetActive(self.Black, isGot)
    KTool.SetActive(self.CanAnim, isCanGet)

    if not isNull(self.FloorReceived) then
        if isCanGet then
            CfUtils.SetColor(self.TxtNumber, XLuaUtils.HexToColor("#FFFFFF"))
            CfUtils.SetColor(self.TxtDay, XLuaUtils.HexToColor("#FFFFFF"))
        else
            CfUtils.SetColor(self.TxtNumber, XLuaUtils.HexToColor("#878787"))
            CfUtils.SetColor(self.TxtDay, XLuaUtils.HexToColor("#878787"))
        end

        KTool.SetActive(self.FloorNormal, isDoing)
    end

    --CfUtils.SetColor(self.Imgbg, isGot and XLuaUtils.HexToColor("#b6b6b6") or XLuaUtils.HexToColor("#ffffff"))
    if isTomorrow then
        CfUtils.SetColor(self.TxtState, XLuaUtils.HexToColor("#626262"))
        self.TxtState.text = localize("明日奖励")
    else
        CfUtils.SetColor(self.TxtState, XLuaUtils.HexToColor("#868686"))
        self.TxtState.text = localize("未达成")
    end

    if isNull(self.CommonGoodsList.Env) then
        self.CommonGoodsList:Init()
    end
    self.CommonGoodsList.Env:FreshBaseUI(data.rewards, false, isGot)
    --self.CommonGoodsList.Env:SetCanGetEffectShow(isCanGet)
end

function UIActivityMultipleSignCellNode:GetLuaIndex()
    return self.cellIndex
end


function UIActivityMultipleSignCellNode:PlayInitAnim()
    if not isNull(self.AnimRoot) then
        self.isAnimate = true
        CfUtils.PlayAnimator(self.AnimRoot, "Default")
    end
end

function UIActivityMultipleSignCellNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end
return UIActivityMultipleSignCellNode